                    counts[value] = counts.get(value, 0) + 1
            background = max(counts, key=counts.get)
            score = sum(v != background for line in tile for v in line)
            candidates.append((score, ri, ci, background, tile))
    _, source_ri, source_ci, background, source = max(candidates)
    sh, sw = len(source), len(source[0])
    out = [line[:] for line in grid]
    for ri, (r0, r1) in enumerate(rows):
